describe('Login Loading Spinner', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should display loading spinner while login request is processing', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('password123');
        cy.get('button[type="submit"]').click();

        cy.get('.loading-spinner').should('be.visible');

        // Simulate waiting for the login request to complete
        cy.intercept('POST', '/api/login', {
            statusCode: 200,
            body: { token: 'fakeToken' }
        }).as('loginRequest');

        cy.wait('@loginRequest');
        cy.get('.loading-spinner').should('not.exist');
    });

    it('should not display loading spinner if login fails', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('wrongpassword');
        cy.get('button[type="submit"]').click();

        cy.get('.loading-spinner').should('be.visible');

        // Simulate waiting for the login request to complete
        cy.intercept('POST', '/api/login', {
            statusCode: 401,
            body: { error: 'Invalid credentials' }
        }).as('loginRequest');

        cy.wait('@loginRequest');
        cy.get('.loading-spinner').should('not.exist');
        cy.get('.error-message').should('contain', 'Invalid credentials');
    });
});
